#!/bin/bash
# Conservative recovery from signed local packages. Metadata is generated by
# pacman in a private DB, never invented. No --overwrite or --nodeps is used.
set -euo pipefail
umask 077
cd "$(dirname "$0")"
. ./package-lock.sh
marker=/var/lib/linuxrunner/pacman-recovery-required
history=/var/log/linuxrunner-package-recovery.log
checkpoint_base=/var/lib/linuxrunner/repair-checkpoints
local_db=/var/lib/pacman/local
native_lock=/var/lib/pacman/db.lck
native_identity=
work=
fail() { echo "PACKAGE_LOCK: category=PACKAGE_DATABASE_RECOVERY_REQUIRED $*"; exit 1; }
progress() { echo "PACKAGE_STAGE: $*"; }
release_database() {
    if [[ -n $native_identity ]]; then
        if [[ ! -L $native_lock && $(stat -c '%d:%i' "$native_lock" 2>/dev/null) == "$native_identity" ]]; then rm -- "$native_lock"; fi
        exec 7>&-
        native_identity=
    fi
}
cleanup() {
    release_database
    # Retain diagnostic/checkpoint metadata, never hundreds of MB of scratch
    # payload after a refused repair. A fresh attempt verifies the archive again.
    if [[ -n $work && $work == "$checkpoint_base"/pacman.* && -d $work && ! -L $work ]]; then
        rm -rf -- "$work/payload"
    fi
}
trap cleanup EXIT
# Reuse only an actual inherited coordinator descriptor for this rootfs.
if [[ $(stat -Lc '%d:%i' /proc/self/fd/9 2>/dev/null || :) != "$(stat -c '%d:%i' /var/lib/linuxrunner/package-operation.lock 2>/dev/null || :)" ]] || ! flock -n 9 2>/dev/null; then
    package_lock_acquire defer-ready || exit $?
fi
[[ $(id -u) == 0 ]] || fail 'package recovery requires the managed administrator process'
for tool in pacman pacman-key pacman-conf bsdtar cmp sha256sum; do command -v "$tool" >/dev/null || fail "recovery tool missing: $tool"; done
[[ ! -L $marker && ! -L $checkpoint_base && ! -L $local_db && ! -L $history ]] || fail 'unsafe recovery metadata path'
[[ $(pacman-conf DBPath) == /var/lib/pacman/ || $(pacman-conf DBPath) == /var/lib/pacman ]] || fail 'custom pacman DBPath requires explicit diagnosis'
mkdir -p "$checkpoint_base" /var/log
# O_EXCL through noclobber, not an advisory substitute for libalpm's own lock.
if ! (set -C; : > "$native_lock") 2>/dev/null; then
    echo 'PACKAGE_LOCK: category=PACKAGE_MANAGER_BUSY another pacman transaction started'; exit 75
fi
exec 7<>"$native_lock"
native_identity=$(stat -c '%d:%i' "$native_lock")
work=$(mktemp -d "$checkpoint_base/pacman.XXXXXXXX")
[[ ! -e $marker ]] || cp -p -- "$marker" "$work/previous-marker"
pacman -Dk > "$work/database-before.log" 2>&1 && db_ok=1 || db_ok=0
names=() versions=()
add_candidate() {
    local name=$1 version=$2 i
    [[ $name =~ ^[a-zA-Z0-9][a-zA-Z0-9+_.-]*$ && ( -z $version || $version =~ ^[a-zA-Z0-9][a-zA-Z0-9+_.:~-]*$ ) ]] || fail 'invalid package identity in damaged metadata'
    for i in "${!names[@]}"; do
        if [[ ${names[i]} == "$name" ]]; then
            [[ -z ${versions[i]} || -z $version || ${versions[i]} == "$version" ]] || fail "ambiguous installed versions for $name"
            [[ -z $version ]] || versions[i]=$version
            return
        fi
    done
    names+=("$name"); versions+=("$version")
    (( ${#names[@]} <= 8 )) || fail 'more than eight damaged packages; recovery requires a reviewed plan'
}
# Recognize an interrupted *managed repair*, even after metadata was published.
if [[ -f $marker ]]; then
    old_checkpoint=$(sed -n 's/^checkpoint=//p' "$marker")
    if [[ -n $old_checkpoint ]]; then
        [[ $old_checkpoint == "$checkpoint_base"/pacman.* && ! -L $old_checkpoint && -d $old_checkpoint ]] || fail 'invalid recovery checkpoint reference'
        case "$(cat "$old_checkpoint/phase" 2>/dev/null || :)" in
            prepared|metadata-restored|reinstalling)
                while IFS=$'\t' read -r n v rest; do add_candidate "$n" "$v"; done < "$old_checkpoint/plan.tsv";;
        esac
    fi
fi
# Missing desc/files, and mismatched NAME/VERSION, are current DB defects.
# A valid meta-package may have an empty files record (e.g. gcc-libs).
shopt -s nullglob
for entry in "$local_db"/*; do
    [[ -d $entry ]] || continue
    [[ ! -L $entry ]] || fail 'symlink inside pacman local database'
    stem=${entry##*/}; name=${stem%-*-*}; version=${stem#"$name"-}
    if [[ ! -s $entry/desc || ! -f $entry/files ]] ||
       [[ $(sed -n '/^%NAME%$/{n;p;q}' "$entry/desc") != "$name" ]] ||
       [[ $(sed -n '/^%VERSION%$/{n;p;q}' "$entry/desc") != "$version" ]]; then
        add_candidate "$name" "$version"
    fi
    [[ ! -L $entry/desc && ! -L $entry/files && ! -L $entry/mtree ]] || fail "unsafe local metadata for $name"
done
# Dk cannot see an entire deleted package entry. The reported GCC executable
# is an explicit sentinel; never infer ownership from a clean Dk alone.
if [[ -e /usr/bin/gcc || -L /usr/bin/gcc ]]; then
    gcc_record=$(pacman -Q gcc 2> "$work/gcc-query.log" || :)
    gcc_owner=$(pacman -Qqo /usr/bin/gcc 2> "$work/gcc-owner.log" || :)
    if [[ -z $gcc_record || $gcc_owner != gcc ]]; then
        gcc_version=
        [[ $gcc_record != gcc\ * ]] || gcc_version=${gcc_record#* }
        [[ $gcc_version != '(null)' ]] || gcc_version=
        add_candidate gcc "$gcc_version"
    fi
fi
if (( ${#names[@]} == 0 )); then
    (( db_ok )) || { cat "$work/database-before.log"; fail "database inconsistency has no safely reconstructable package entry; details=$work"; }
    if [[ -e $marker ]]; then
        progress 'Rechecking the repaired package database and installed files'
        pacman -Qk > "$work/files-before.log" 2>&1 || { tail -n 12 "$work/files-before.log"; fail "installed package files still need repair; details=$work"; }
        printf 'phase=validated-healthy\n' > "$work/result"
        printf 'time=%s result=healthy obsolete-marker=cleared checkpoint=%s\n' "$(date +%s)" "$work" >> "$history"
        rm -- "$marker"
        progress 'Package database and ownership checks passed; continuing installation'
    fi
    exit 0
fi
progress 'Validating cached signed packages for interrupted installation recovery'
mkdir "$work/db" "$work/owners" "$work/original-entries" "$work/payload"
cp -a "$local_db" "$work/db/local"
for i in "${!names[@]}"; do
    n=${names[i]}
    for entry in "$work/db/local/"*; do
        [[ -d $entry ]] || continue
        stem=${entry##*/}; [[ ${stem%-*-*} == "$n" ]] || continue
        mv -- "$entry" "$work/original-entries/$stem"
    done
done
cp -a "$work/db/local" "$work/owners/local"
# Preserve configured options/repos. The final options section strengthens
# local-package signature policy and is checked through pacman-conf.
cat /etc/pacman.conf > "$work/pacman.conf"
printf '\n[options]\nLocalFileSigLevel = Required TrustedOnly\n' >> "$work/pacman.conf"
policy=$(pacman-conf --config "$work/pacman.conf" LocalFileSigLevel)
[[ $policy == *Required* && $policy != *Optional* && $policy != *Never* && $policy != *TrustAll* ]] || fail 'strict local package signature policy could not be established'
archives=()
: > "$work/plan.tsv"
for i in "${!names[@]}"; do
    n=${names[i]}; v=${versions[i]}; matches=()
    for archive in /var/cache/pacman/pkg/"$n"-[0-9]*.pkg.tar.{xz,zst,gz}; do
        [[ -f $archive && ! -L $archive ]] || continue
        info=$(bsdtar --fast-read -xOf "$archive" .PKGINFO 2>> "$work/archive-inspection.log") || continue
        pkg_name=$(printf '%s\n' "$info" | sed -n 's/^pkgname = //p')
        pkg_version=$(printf '%s\n' "$info" | sed -n 's/^pkgver = //p')
        pkg_arch=$(printf '%s\n' "$info" | sed -n 's/^arch = //p')
        [[ $pkg_name == "$n" && ( $pkg_arch == aarch64 || $pkg_arch == any ) && ( -z $v || $v == "$pkg_version" ) ]] || continue
        matches+=("$archive")
    done
    (( ${#matches[@]} == 1 )) || fail "cannot select one exact cached package for $n (matches=${#matches[@]}); no live database entries or package files changed; details=$work"
    archive=${matches[0]}
    [[ -f $archive.sig && ! -L $archive.sig ]] || fail "trusted detached signature missing for ${archive##*/}; no package files changed"
    pacman-key --verify "$archive.sig" "$archive" > "$work/$n-signature.log" 2>&1 || { tail -n 8 "$work/$n-signature.log"; fail "cached signature failed for $n"; }
    pacman --config "$work/pacman.conf" --dbpath "$work/db" --logfile "$work/staged-pacman.log" -U --dbonly --noscriptlet --noconfirm "$archive" > "$work/$n-metadata.log" 2>&1 || { tail -n 12 "$work/$n-metadata.log"; fail "pacman could not reconstruct $n in its private database"; }
    record=$(pacman --dbpath "$work/db" -Q "$n" 2>> "$work/archive-inspection.log")
    v=${record#* }; versions[i]=$v; archives+=("$archive")
    printf '%s\t%s\t%s\t%s\n' "$n" "$v" "$archive" "$(sha256sum "$archive" | cut -d' ' -f1)" >> "$work/plan.tsv"
    bsdtar -tf "$archive" > "$work/$n-members"
    while IFS= read -r member; do
        member=${member#./}
        [[ $member != /* && $member != '..' && $member != ../* && $member != */../* && $member != */.. && $member != *\\* && $member != *[[:space:]]* ]] || fail "unsupported archive path in $n"
    done < "$work/$n-members"
    mkdir "$work/payload/$n"
    progress "Reading the signed $n payload for comparison; existing files are preserved"
    bsdtar --no-same-owner --no-same-permissions -xf "$archive" -C "$work/payload/$n" || fail "could not stage signed payload for $n"
    batch=(); checked=0
    check_owners() {
        (( ${#batch[@]} )) || return 0
        rc=0; pacman --config /dev/null --dbpath "$work/owners" -Qqo -- "${batch[@]}" > "$work/owners.out" 2> "$work/owners-current.log" || rc=$?
        cat "$work/owners-current.log" >> "$work/owners.log"
        [[ ! -s $work/owners.out ]] || { cat "$work/owners.out"; fail "another installed package owns paths in $n; automatic reassignment refused"; }
        # pacman returns the *number* of unowned paths, not just exit 1.
        # Require its exact expected diagnostic for every requested path.
        (( rc == ${#batch[@]} )) || fail 'ownership queries failed'
        printf 'error: No package owns %s\n' "${batch[@]}" > "$work/owners-expected.log"
        cmp -s "$work/owners-current.log" "$work/owners-expected.log" || fail 'unexpected ownership-query diagnostics'
        batch=()
    }
    while IFS= read -r member; do
        member=${member#./}; member=${member%/}
        [[ -n $member && $member != . ]] || continue
        case "$member" in .PKGINFO|.BUILDINFO|.MTREE|.INSTALL|.CHANGELOG) continue;; esac
        staged="$work/payload/$n/$member"; live="/$member"
        if [[ -d $staged && ! -L $staged ]]; then
            [[ ! -e $live && ! -L $live || -d $live && ! -L $live ]] || fail "directory/type conflict: $live"
            continue
        fi
        if [[ -e $live || -L $live ]]; then
            if [[ -L $staged ]]; then
                [[ -L $live && $(readlink "$staged") == "$(readlink "$live")" ]] || fail "existing link differs from signed $n payload: $live"
            elif [[ -f $staged ]]; then
                [[ -f $live && ! -L $live ]] && cmp -s -- "$staged" "$live" || fail "existing file differs from signed $n payload: $live; no package files overwritten"
            else fail "unsupported package member type: $member"; fi
        fi
        batch+=("$live"); ((checked+=1))
        if (( ${#batch[@]} == 32 )); then check_owners; fi
        if (( checked % 256 == 0 )); then progress "Checking $n recovery files: $checked verified"; fi
    done < "$work/$n-members"
    check_owners
done
pacman --dbpath "$work/db" -Dk > "$work/database-staged.log" 2>&1 || { cat "$work/database-staged.log"; fail 'reconstructed database did not pass dependency/integrity validation'; }
# A reconstruction may add only the selected packages; no other version or
# ownership record may disappear as a side effect of dependency resolution.
pacman --dbpath "$work/owners" -Q > "$work/inventory-before" 2> "$work/inventory-before.log"
pacman --dbpath "$work/db" -Q > "$work/inventory-after" 2> "$work/inventory-after.log"
cp "$work/inventory-after" "$work/inventory-unrelated"
for n in "${names[@]}"; do
    awk -v name="$n" '$1 != name' "$work/inventory-unrelated" > "$work/inventory-filtered"
    mv "$work/inventory-filtered" "$work/inventory-unrelated"
done
cmp -s "$work/inventory-before" "$work/inventory-unrelated" || fail 'reconstruction changed unrelated package records'
printf 'prepared\n' > "$work/phase"
new_marker=$(mktemp /var/lib/linuxrunner/.pacman-recovery.XXXXXX)
printf 'version=2\ncheckpoint=%s\n' "$work" > "$new_marker"
sync -d "$work/plan.tsv" "$work/phase" "$new_marker"
mv -- "$new_marker" "$marker"
for i in "${!names[@]}"; do
    n=${names[i]}; v=${versions[i]}
    for entry in "$local_db/"*; do
        [[ -d $entry ]] || continue
        stem=${entry##*/}; [[ ${stem%-*-*} == "$n" ]] || continue
        mv -- "$entry" "$work/live-original-$stem"
    done
    mv -- "$work/db/local/$n-$v" "$local_db/$n-$v"
    sync -d "$local_db/$n-$v/desc" "$local_db/$n-$v/files"
done
printf 'metadata-restored\n' > "$work/phase"; sync -d "$work/phase"
release_database
progress 'Reinstalling validated packages with normal signature and conflict checks'
printf 'reinstalling\n' > "$work/phase"; sync -d "$work/phase"
pacman --config "$work/pacman.conf" -U --noconfirm "${archives[@]}" > "$work/reinstall.log" 2>&1 || { tail -n 16 "$work/reinstall.log"; fail "normal signed reinstall failed; checkpoint=$work"; }
pacman -Dk > "$work/database-after.log" 2>&1 || { cat "$work/database-after.log"; fail 'package database still fails verification after reinstall'; }
for n in "${names[@]}"; do
    pacman -Q "$n"
    pacman -Qk "$n" > "$work/$n-files-after.log" 2>&1 || { cat "$work/$n-files-after.log"; fail "installed files remain incomplete for $n"; }
done
if [[ -e /usr/bin/gcc ]]; then
    [[ $(pacman -Qqo /usr/bin/gcc) == gcc ]] || fail 'GCC executable remains unowned after repair'
    /usr/bin/gcc --version > "$work/gcc-execution.log" 2>&1 || fail 'GCC ownership restored but executable does not run'
fi
printf 'verified\n' > "$work/phase"; sync -d "$work/phase"
printf 'time=%s result=repaired packages=%s signature=required database=verified ownership=verified checkpoint=%s\n' "$(date +%s)" "${names[*]}" "$work" >> "$history"
rm -- "$marker"
# Payloads are disposable scratch; retain original metadata and every log.
rm -rf -- "$work/payload"
progress 'Package database and ownership repaired; resuming installation'
